// One fixed damage budget: isolate a target instead of multiplying AoE damage.
const SHARED_COMET_SIGNATURE=['等分の星雨',28,7,'照準地点に予告円を置き、0.9秒後に半径160へ合計600%の威力を均等分配。着弾時に円内にいる敵1体なら600%、3体なら各200%。途中で倒れた敵の取り分は再配分しない。壁の向こうには当たらない。自分が着弾点から500を超える・壁に隠れる・死亡・地域移動で解除。範囲補正は円の半径だけを変える。属性抽選で分配方法は変わらない。','M26 4V19M18 10L26 19L34 10M26 19L9 40M26 19V44M26 19L43 40M4 40H14M21 44H31M38 40H48'];
SIGNATURE_SKILLS.push(SHARED_COMET_SIGNATURE);Object.assign(GEM.crafted_5_4,{name:SHARED_COMET_SIGNATURE[0],cost:28,cool:7,desc:SHARED_COMET_SIGNATURE[3],ability:null,signature:100,tags:['spell','area']});
SIGNATURE_AUDIO.push(['sharedcomet',520,.4]);SKILL_AUDIO_FAMILIES.metal.add('sharedcomet');
function sharedCometValid(s){return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&dist(p,s)<=500&&lineClear(p,s);}
function sharedCometTargets(s){return enemies.filter(e=>e.hp>0&&dist(e,s)<=160*s.build.radius&&lineClear(s,e));}
const sharedCometCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=sharedCometCastBase(build,...args);if(GEM[build.type]?.signature!==100)return result;let s=signatureSpells.at(-1);if(s?.mode!==100)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==100||v===s);s.owner=p;s.world=dungeon;s.finished=false;s.target=null;return result;};
const sharedCometStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==100)return sharedCometStepBase(s,dt);if(!sharedCometValid(s))return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time+1e-8<.9)return true;const targets=sharedCometTargets(s),amount=targets.length?s.damage*6/targets.length:0;s.finished=true;for(const e of targets)if(e.hp>0&&enemies.includes(e))spellHit(e,amount,s.build);burst(s.x,s.y,160*s.build.radius,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(100,true,s.x,s.y);return false;};
const sharedCometPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{sharedCometPaintBase();for(const s of signatureSpells){if(s.mode!==100||!sharedCometValid(s)||!visibleAt(s.x,s.y))continue;const color=ELEMENTS[s.build.elements[0]].color;groundRing(s.x,s.y,160*s.build.radius,color,2);groundRing(s.x,s.y,Math.max(4,160*s.build.radius*(1-s.time/.9)),'#f5e8bc',2);for(const e of sharedCometTargets(s))if(visibleAt(e.x,e.y))paintLinkLine(s,e,color,1);}};
const sharedCometStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===100?{label:'等分 '+sharedCometTargets(s).length+'体',value:Math.min(1,s.time/.9),waiting:true}:sharedCometStatusBase(s);
